    Returns:
    - str: A status message indicating the server's operation and run duration.

    Requirements:
    - socket
    - select
    - queue
    - datetime

    Example:
    >>> print(task_func())
    'Server started on localhost:12345. Ran for 5 seconds.'
    """
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setblocking(0)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((server_address, server_port))
    server.listen(5)

    inputs = [server]
    outputs = []
    message_queues = {}

    def close_socket(s):
        if s in outputs:
            outputs.remove(s)
        if s in inputs:
            inputs.remove(s)
        if s in message_queues:
            del message_queues[s]
        try:
            s.close()
        except Exception:
            pass

    end_time = datetime.now() + timedelta(seconds=run_duration)

    try:
        while datetime.now() < end_time:
            time_left = (end_time - datetime.now()).total_seconds()
            if time_left <= 0:
                break

            readable, writable, exceptional = select.select(
                inputs, outputs, inputs, min(time_left, 1)
            )

            for s in readable:
                if s is server:
                    try:
                        connection, client_address = s.accept()
                        connection.setblocking(0)
                        inputs.append(connection)
                        message_queues[connection] = queue.Queue()
                    except Exception:
                        pass
                else:
                    try:
                        data = s.recv(buffer_size)
                        if data:
                            current_time = datetime.now().strftime(
                                "%Y-%m-%d %H:%M:%S"
                            )
                            response = data + f" {current_time}".encode()
                            message_queues.setdefault(s, queue.Queue()).put(response)
                            if s not in outputs:
                                outputs.append(s)
                        else:
                            # Peer closed connection; only close it once
                            # any pending queued responses have been flushed
                            # (i.e., there's nothing more to write out).
                            if s in message_queues and not message_queues[s].empty():
                                # keep it in outputs so pending data can still
                                # be sent, but stop reading from it further by
                                # simply not re-adding to inputs read set
                                # (it will be removed once queue drains)
                                if s in inputs:
                                    inputs.remove(s)
                            else:
                                close_socket(s)
                    except Exception:
                        close_socket(s)

            for s in writable:
                if s in message_queues:
                    q = message_queues[s]
                    try:
                        next_msg = q.get_nowait()
                    except queue.Empty:
                        if s in outputs:
                            outputs.remove(s)
                        # If socket was already removed from inputs (peer
                        # closed) and queue is now empty, close it now.
                        if s not in inputs:
                            close_socket(s)
                    else:
                        try:
                            sent = s.send(next_msg)
                            if sent < len(next_msg):
                                # Requeue the unsent remainder at the front
