import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    """Run a non-blocking timestamping echo server for ``run_duration`` seconds."""
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((server_address, server_port))
    server.listen()
    server.setblocking(False)

    inputs = [server]
    outputs = []
    message_queues = {}
    deadline = datetime.now() + timedelta(seconds=run_duration)

    def close_client(sock):
        if sock in inputs:
            inputs.remove(sock)
        if sock in outputs:
            outputs.remove(sock)
        message_queues.pop(sock, None)
        try:
            sock.close()
        except OSError:
            pass

    try:
        while inputs and datetime.now() < deadline:
            remaining = max(0, (deadline - datetime.now()).total_seconds())
            readable, writable, exceptional = select.select(
                inputs, outputs, inputs, remaining
            )

            for sock in readable:
                if sock is server:
                    try:
                        client, _ = server.accept()
                        client.setblocking(False)
                        inputs.append(client)
                        message_queues[client] = queue.Queue()
                    except OSError:
                        pass
                else:
                    try:
                        data = sock.recv(buffer_size)
                    except OSError:
                        close_client(sock)
                        continue

                    if data:
                        timestamp = datetime.now().isoformat().encode("utf-8")
                        message_queues[sock].put(data + b" " + timestamp)
                        if sock not in outputs:
                            outputs.append(sock)
                    else:
                        close_client(sock)

            for sock in writable:
                try:
                    message = message_queues[sock].get_nowait()
                    sock.sendall(message)
                except queue.Empty:
                    if sock in outputs:
                        outputs.remove(sock)
                except OSError:
                    close_client(sock)

            for sock in exceptional:
                if sock is not server:
                    close_client(sock)
    finally:
        for sock in list(inputs):
            try:
                sock.close()
            except OSError:
                pass

    return (
        f"Server started on {server_address}:{server_port}. "
        f"Ran for {run_duration} seconds."
    )
