IMAGE_PATH = "image.png"


def task_func(filename=IMAGE_PATH, from_encoding="cp1251", to_encoding="utf8"):
    def convert(value):
        try:
            codecs.lookup(from_encoding)
            codecs.lookup(to_encoding)

            if isinstance(value, bytes):
                text = codecs.decode(value, from_encoding)
            else:
                text = str(value)

            return codecs.decode(codecs.encode(text, to_encoding), to_encoding)
        except (UnicodeError, LookupError) as exc:
            raise ValueError("Invalid encoding conversion") from exc

    try:
        image = Image.open(filename)
    except Exception:
        return ""

    try:
        extracted_text = pytesseract.image_to_string(image)
    except Exception:
        extracted_text = None

    if extracted_text is not None:
        return convert(extracted_text)

    try:
        comment = image.info.get("comment", "")
        return convert(comment) if comment else ""
    except (UnicodeError, LookupError) as exc:
        raise ValueError("Invalid encoding conversion") from exc
    except Exception:
        return ""
