import requests
from lxml import html
import pandas as pd
import sqlite3


def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    """
    This function parses HTML table data from a specified URL or local file and stores it into an SQLite database.
    """
    # Fetch content
    if webpage_url.startswith("file://"):
        file_path = webpage_url[len("file://"):]
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read()
    else:
        try:
            response = requests.get(webpage_url, timeout=10)
            response.raise_for_status()
            content = response.content
        except requests.RequestException:
            raise

    # Parse table using lxml
    try:
        tree = html.fromstring(content if isinstance(content, (bytes, str)) else str(content))
        tables = tree.xpath('//table')
    except Exception:
        tables = []

    if not tables:
        return 0

    table_element = tables[0]

    # Extract rows and headers
    rows = table_element.xpath('.//tr')
    if not rows:
        return 0

    data = []
    header = None
    for i, row in enumerate(rows):
        cells = row.xpath('.//th | .//td')
        cell_text = [c.text_content().strip() for c in cells]
        if not cell_text:
            continue
        if i == 0 and row.xpath('.//th'):
            header = cell_text
        else:
            data.append(cell_text)

    if not data:
        return 0

    if header and len(header) == len(data[0]):
        df = pd.DataFrame(data, columns=header)
    else:
        df = pd.DataFrame(data)

    if df.empty:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.commit()
    except sqlite3.DatabaseError:
        raise
    finally:
        try:
            conn.close()
        except Exception:
            pass

    return len(df)
