        for key, value in record.items():
            values_by_key[key]  # Ensure keys with no numeric values are retained.
            if isinstance(value, (int, float, np.number)) and not isinstance(value, bool):
                if not np.isnan(value):
                    values_by_key[key].append(value)

    results = {}
    for key, values in values_by_key.items():
        if values:
            results[key] = {
                "mean": np.mean(values),
                "median": np.median(values),
            }
        else:
            results[key] = {"mean": np.nan, "median": np.nan}

    return pd.DataFrame.from_dict(results, orient="index", columns=["mean", "median"]).sort_index()
