import requests
from bs4 import BeautifulSoup
import pandas as pd


def task_func(url="http://example.com"):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.HTTPError:
        raise
    except requests.RequestException as exc:
        raise ConnectionError(f"Could not connect to {url}") from exc

    try:
        soup = BeautifulSoup(response.content, "html.parser")
        table = soup.find("table")
        if table is None:
            raise ValueError("No table found on the page.")

        rows = table.find_all("tr")
        if not rows:
            raise ValueError("No table data found on the page.")

        first_row = rows[0]
        headers = [
            cell.get_text(" ", strip=True)
            for cell in first_row.find_all("th", recursive=False)
        ]

        data = []
        for row in rows:
            cells = row.find_all("td", recursive=False)
            if cells:
                data.append([cell.get_text(" ", strip=True) for cell in cells])

        if not data:
            raise ValueError("No table data found on the page.")

        return pd.DataFrame(data, columns=headers if headers else None)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("Page content could not be parsed.") from exc
